/* Sekreter renderer: 06-office-cases.js */
let MUVEKKIL_KARTLARI=[],DAVA_DOSYALARI=[],DOSYA_MUVEKKIL_BAGLARI=[];
async function buroKartlariYukle(){
  if(!_buro)return;
  const[m,d]=await Promise.all([
    sb.from('muvekkiller').select('*').eq('buro_id',_buro.id).order('ad'),
    sb.from('dava_dosyalari').select('*').eq('buro_id',_buro.id).order('updated_at',{ascending:false})
  ]);
  if(m.error||d.error){alert('Büro kartları yüklenemedi: '+(m.error?.message||d.error?.message));return;}
  const dosyaIds=(d.data||[]).map(x=>x.id);
  const b=dosyaIds.length?await sb.from('dava_dosyasi_muvekkilleri').select('dava_dosyasi_id,muvekkil_id').in('dava_dosyasi_id',dosyaIds):{data:[],error:null};
  if(b.error){alert('Dosya–müvekkil bağlantıları yüklenemedi: '+b.error.message);return;}
  MUVEKKIL_KARTLARI=m.data||[];DAVA_DOSYALARI=d.data||[];DOSYA_MUVEKKIL_BAGLARI=b.data||[];renderBuroKartlari();
}
function renderBuroKartlari(){
  const q=(document.getElementById('buro-kart-arama')?.value||'').toLocaleLowerCase('tr-TR');
  const norm=s=>String(s||'').toLocaleLowerCase('tr-TR');
  const ml=MUVEKKIL_KARTLARI.filter(m=>[m.ad,m.telefon,m.email,m.kimlik_vergi_no].some(x=>norm(x).includes(q)));
  const dl=DAVA_DOSYALARI.filter(d=>[d.dosya_no,d.mahkeme,d.konu,d.notlar].some(x=>norm(x).includes(q)));
  document.getElementById('muvekkil-kart-sayi').textContent='('+ml.length+')';document.getElementById('dosya-kart-sayi').textContent='('+dl.length+')';
  document.getElementById('muvekkil-kart-list').innerHTML=ml.length?ml.map(m=>{
    const isler=records.filter(r=>String(r.muvekkilId||'')===String(m.id)||norm(r.muvekkil)===norm(m.ad));
    return `<div style="padding:12px 13px;border-bottom:1px solid var(--border);cursor:pointer;" onclick="openBuroKartDetay('muvekkil',${m.id})"><div style="display:flex;justify-content:space-between;gap:8px;"><b style="font-size:13px;">${esc(m.ad)}</b><span style="font-size:11px;color:var(--text3);">${isler.length} iş</span></div><div style="font-size:11px;color:var(--text2);margin-top:4px;">${esc([m.telefon,m.email].filter(Boolean).join(' · ')||'İletişim bilgisi yok')}</div></div>`;
  }).join(''):'<div class="empty-state" style="padding:18px;">Henüz müvekkil kartı yok.</div>';
  document.getElementById('dosya-kart-list').innerHTML=dl.length?dl.map(d=>{
    const isler=records.filter(r=>String(r.davaDosyasiId||'')===String(d.id)||norm(r.dava)===norm(d.dosya_no));
    return `<div style="padding:12px 13px;border-bottom:1px solid var(--border);cursor:pointer;" onclick="openBuroKartDetay('dosya',${d.id})"><div style="display:flex;justify-content:space-between;gap:8px;"><b style="font-size:13px;">${esc(d.dosya_no||'Dosya numarası yok')}</b><span class="badge">${esc(d.durum||'açık')}</span></div><div style="font-size:11px;color:var(--text2);margin-top:4px;">${esc([d.mahkeme,d.konu].filter(Boolean).join(' · ')||'Dosya ayrıntısı yok')} · ${isler.length} iş</div></div>`;
  }).join(''):'<div class="empty-state" style="padding:18px;">Henüz dava dosyası kartı yok.</div>';
}
function closeBuroKartDetay(){const o=document.getElementById('buro-kart-detay-overlay');if(o)o.style.display='none';}
function kartYonetimButonlariniEkle(tur,id){
  if(_buro?.rol!=='yonetici')return;const govde=document.querySelector('#buro-kart-detay-overlay .modal-body');if(!govde)return;
  const b=document.createElement('button');b.className='btn';b.style.cssText='width:100%;margin-top:8px;color:#b42318;border-color:#fda29b;';b.textContent=tur==='muvekkil'?'Müvekkili Sil':'Dosyayı Sil';b.onclick=()=>kartSil(tur,id);govde.appendChild(b);
}
function openKartBirlestir(tur){
  if(_buro?.rol!=='yonetici'){alert('Bu işlem yalnızca büro yöneticisine açıktır.');return;}
  const liste=tur==='muvekkil'?MUVEKKIL_KARTLARI:DAVA_DOSYALARI,ad=x=>tur==='muvekkil'?x.ad:[x.dosya_no,x.mahkeme].filter(Boolean).join(' · ');
  if(liste.length<2){alert('Birleştirmek için en az iki kart bulunmalıdır.');return;}
  let o=document.getElementById('kart-birlestir-overlay');if(!o){o=document.createElement('div');o.id='kart-birlestir-overlay';o.className='modal-overlay';o.style.zIndex='580';document.body.appendChild(o);}
  const secenek='<option value="">Seçiniz...</option>'+liste.slice().sort((a,b)=>ad(a).localeCompare(ad(b),'tr')).map(x=>`<option value="${x.id}">${esc(ad(x)||'İsimsiz kart')}</option>`).join('');
  o.innerHTML=`<div class="modal" style="max-width:500px;"><div class="modal-header"><div><h2>${tur==='muvekkil'?'Müvekkil':'Dosya'} Birleştir</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">Bağlı kayıtlar hedef karta taşınır, kaynak kart silinir.</div></div><button class="btn" onclick="document.getElementById('kart-birlestir-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Silinecek tekrar kart</label><select id="kart-birlestir-kaynak">${secenek}</select></div><div class="fg"><label>Korunacak ana kart</label><select id="kart-birlestir-hedef">${secenek}</select></div><div style="padding:11px;background:#fff7ed;border-radius:9px;font-size:11px;color:#9a3412;margin-bottom:12px;">Kaynak kartın takvim ve dosya bağlantıları korunacak ana karta aktarılır. İşlem geri alınamaz.</div><button id="kart-birlestir-btn" class="save-btn" onclick="kartBirlestir('${tur}')">Kayıtları Birleştir</button><div id="kart-birlestir-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';
}
async function kartBirlestir(tur){
  const kaynak=document.getElementById('kart-birlestir-kaynak').value,hedef=document.getElementById('kart-birlestir-hedef').value,msg=document.getElementById('kart-birlestir-msg'),btn=document.getElementById('kart-birlestir-btn');
  if(!kaynak||!hedef||kaynak===hedef){msg.textContent='Birbirinden farklı iki kart seçin.';return;}if(!confirm('Kaynak kart hedef kartla birleştirilecek ve kaynak kart silinecek. Devam edilsin mi?'))return;
  btn.disabled=true;btn.textContent='Birleştiriliyor...';const fn=tur==='muvekkil'?'sekreter_muvekkil_birlestir':'sekreter_dosya_birlestir',{error}=await sb.rpc(fn,{kaynak_id:Number(kaynak),hedef_id:Number(hedef)});
  if(error){msg.textContent='Birleştirme hatası: '+error.message;btn.disabled=false;btn.textContent='Kayıtları Birleştir';return;}document.getElementById('kart-birlestir-overlay').style.display='none';await loadRecords();await buroKartlariYukle();
}
async function kartSil(tur,id){
  if(_buro?.rol!=='yonetici'){alert('Bu işlem yalnızca büro yöneticisine açıktır.');return;}
  const ad=tur==='muvekkil'?MUVEKKIL_KARTLARI.find(x=>String(x.id)===String(id))?.ad:DAVA_DOSYALARI.find(x=>String(x.id)===String(id))?.dosya_no;
  const uyari=tur==='muvekkil'?'Müvekkil kartı silinecek; takvim kayıtları korunacak fakat müvekkil bağlantısı kaldırılacak.':'Dosya; işlem geçmişi, mali hareketleri ve evraklarıyla birlikte kalıcı olarak silinecek.';
  if(!confirm(`${ad||'Bu kayıt'}\n\n${uyari}\n\nDevam edilsin mi?`))return;
  if(tur==='dosya'){
    const{data,error}=await sb.from('dosya_evraklari').select('storage_yolu').eq('dava_dosyasi_id',id);if(error){alert('Evrak listesi alınamadı: '+error.message);return;}
    const yollar=(data||[]).map(x=>x.storage_yolu).filter(Boolean);for(let i=0;i<yollar.length;i+=100){const r=await sb.storage.from('sekreter-evraklari').remove(yollar.slice(i,i+100));if(r.error){alert('Evraklar silinemedi, dosya silme durduruldu: '+r.error.message);return;}}
  }
  const fn=tur==='muvekkil'?'sekreter_muvekkil_sil':'sekreter_dosya_sil',{error}=await sb.rpc(fn,{kaynak_id:Number(id)});if(error){alert('Silme hatası: '+error.message);return;}closeBuroKartDetay();await loadRecords();await buroKartlariYukle();
}
function kartDetayKayitlariHTML(liste){
  if(!liste.length)return '<div class="empty-state" style="padding:14px;">Bağlı takvim kaydı yok.</div>';
  return liste.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(r=>`<div style="padding:9px 11px;border-bottom:1px solid var(--border);cursor:pointer;" onclick="closeBuroKartDetay();openKayitModal(${r.id})"><div style="display:flex;justify-content:space-between;gap:10px;"><b style="font-size:12px;">${esc(getBaslik(r))}</b><span style="font-size:11px;white-space:nowrap;${r.tamamlandi?'color:#16a34a;':'color:var(--text2);'}">${r.tamamlandi?'✓ ':''}${formatDate(r.date)}</span></div><div style="font-size:10px;color:var(--text3);margin-top:3px;">${esc(typeLabel(r.type,r.dal))}${r.saat?' · '+esc(r.saat):''}</div></div>`).join('');
}
function tl(v){return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(Number(v)||0);}
async function maliTakipHTML(dosyaId,d){
  const{data,error}=await sb.from('dosya_mali_hareketleri').select('*').eq('dava_dosyasi_id',dosyaId).order('tarih',{ascending:false});
  if(error)return `<div class="section-title">Ücret ve Masraf Takibi</div><div style="padding:12px;background:#fff7ed;border-radius:10px;font-size:12px;margin-bottom:16px;">Mali takip kurulumu bekleniyor. Hazırlanan SQL dosyasını Supabase'de bir kez çalıştırın.</div>`;
  const h=data||[],t=h.filter(x=>x.tur==='tahsilat').reduce((n,x)=>n+Number(x.tutar),0),m=h.filter(x=>x.tur==='masraf').reduce((n,x)=>n+Number(x.tutar),0),mt=h.filter(x=>x.tur==='masraf_tahsilati').reduce((n,x)=>n+Number(x.tutar),0),u=typeof maliDosyaAnlasmaTutari==='function'?maliDosyaAnlasmaTutari(d):Number(d.anlasilan_ucret)||0,k=Math.max(0,u-t),mk=Math.max(0,m-mt);
  const kartlar=[['Anlaşılan Ücret',tl(u)],['Ücret Tahsilatı',tl(t)],['Kalan Ücret',tl(k)],['Toplam Masraf',tl(m)],['Tahsil Edilen Masraf',tl(mt)],['Kalan Masraf',tl(mk)]].map((x,i)=>`<div style="background:${((i===2&&k>0)||(i===5&&mk>0))?'#fff7ed':'var(--surface2)'};padding:9px;border-radius:9px;"><div style="font-size:9px;color:var(--text3);">${x[0]}</div><b style="font-size:12px;">${x[1]}</b></div>`).join('');
  const turAdi={tahsilat:'Ücret Tahsilatı',masraf:'Masraf',masraf_tahsilati:'Masraf Tahsilatı'};
  const liste=h.length?`<div style="margin-top:10px;max-height:170px;overflow:auto;">${h.map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;padding:7px 2px;border-top:1px solid var(--border);font-size:11px;"><span><b>${turAdi[x.tur]||x.tur}</b> · ${formatDate(x.tarih)}${x.aciklama?' · '+esc(x.aciklama):''}</span><span style="white-space:nowrap;">${tl(x.tutar)} <button style="border:0;background:none;color:var(--text2);cursor:pointer;" onclick="maliHareketDuzenle('${x.id}','${dosyaId}')">Düzenle</button> <button style="border:0;background:none;color:#dc2626;cursor:pointer;" onclick="maliHareketSil('${x.id}','${dosyaId}')">Sil</button></span></div>`).join('')}</div>`:'<div style="font-size:11px;color:var(--text3);margin-top:10px;">Henüz hareket yok.</div>';
  return `<div class="section-title">Ücret ve Masraf Takibi</div><div style="border:1px solid var(--border);border-radius:12px;padding:12px;margin-bottom:16px;"><div style="display:grid;grid-template-columns:repeat(3,minmax(120px,1fr));gap:7px;overflow:auto;margin-bottom:11px;">${kartlar}</div><div style="display:flex;gap:7px;flex-wrap:wrap;"><button class="btn btn-primary" onclick="openMaliHareketFormu(${dosyaId},'tahsilat')">＋ Ücret Tahsilatı</button><button class="btn" onclick="openMaliHareketFormu(${dosyaId},'masraf')">＋ Masraf</button><button class="btn" onclick="openMaliHareketFormu(${dosyaId},'masraf_tahsilati')">＋ Masraf Tahsilatı</button><button class="btn" onclick="anlasilanUcretDuzenle(${dosyaId},${u})">Ücreti Belirle</button></div>${liste}</div>`;
}
function openDosyaMaliSecimFormu(){
  let o=document.getElementById('dosya-mali-secim-overlay');if(!o){o=document.createElement('div');o.id='dosya-mali-secim-overlay';o.className='modal-overlay';o.style.zIndex='545';document.body.appendChild(o);}
  const dosyalar=[...DAVA_DOSYALARI].sort((a,b)=>String(a.dosya_no||'').localeCompare(String(b.dosya_no||''),'tr'));
  o.innerHTML=`<div class="modal" style="max-width:560px;"><div class="modal-header"><div><h2>Dosya Parası / Masraf Ekle</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">Dosya numarası, müvekkil veya mahkeme adıyla arayın.</div></div><button class="btn" onclick="document.getElementById('dosya-mali-secim-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Dosya veya müvekkil ara</label><input id="dosya-mali-ara" type="search" placeholder="Örn. 2026/100, Ahmet Yılmaz..." oninput="dosyaMaliListesiniFiltrele()" autocomplete="off"></div><input id="dosya-mali-secim-dosya" type="hidden"><div class="fg"><label>Arama sonuçları</label><div id="dosya-mali-sonuclar" class="list-surface" style="max-height:230px;overflow:auto;"></div></div><div class="fg"><label>Yapılacak işlem</label><select id="dosya-mali-secim-tur"><option value="tahsilat">Müvekkilden ücret tahsilatı</option><option value="masraf">Dosya için yapılan masraf</option><option value="masraf_tahsilati">Müvekkilden masraf tahsilatı</option><option value="anlasilan">Anlaşılan toplam ücreti belirle</option></select></div><button class="save-btn" onclick="dosyaMaliSecimiDevam()">Devam Et</button><div id="dosya-mali-secim-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';dosyaMaliListesiniFiltrele();setTimeout(()=>document.getElementById('dosya-mali-ara')?.focus(),50);
}
function maliAramaNorm(s){return String(s||'').trim().toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function dosyaMaliListesiniFiltrele(){const q=maliAramaNorm(document.getElementById('dosya-mali-ara')?.value||''),c=document.getElementById('dosya-mali-sonuclar'),secili=document.getElementById('dosya-mali-secim-dosya')?.value;if(!c)return;const bulunan=DAVA_DOSYALARI.filter(d=>!q||maliAramaNorm([d.dosya_no,d.mahkeme,d.konu,dosyaMuvekkilAdlari(d.id)].filter(Boolean).join(' ')).includes(q)).sort((a,b)=>String(a.dosya_no||'').localeCompare(String(b.dosya_no||''),'tr'));c.innerHTML=bulunan.length?bulunan.map(d=>`<button type="button" data-id="${d.id}" onclick="dosyaMaliDosyaSec(this.dataset.id)" style="display:block;width:100%;text-align:left;border:0;border-bottom:1px solid var(--border);padding:10px 12px;cursor:pointer;background:${String(secili)===String(d.id)?'var(--green-light)':'var(--surface)'};"><b style="font-size:12px;">${esc(d.dosya_no||'Numarasız dosya')}</b><div style="font-size:11px;color:var(--text2);margin-top:3px;">${esc(dosyaMuvekkilAdlari(d.id)||'Müvekkil bağlanmamış')}</div><div style="font-size:10px;color:var(--text3);margin-top:2px;">${esc(d.mahkeme||d.konu||'Mahkeme bilgisi yok')}</div></button>`).join(''):'<div class="empty-state" style="padding:16px;">Eşleşen dosya bulunamadı.</div>';}
function dosyaMaliDosyaSec(id){document.getElementById('dosya-mali-secim-dosya').value=id;document.getElementById('dosya-mali-secim-msg').textContent='✓ Dosya seçildi';dosyaMaliListesiniFiltrele();}
function dosyaMuvekkilAdlari(dosyaId){const ids=new Set(DOSYA_MUVEKKIL_BAGLARI.filter(x=>String(x.dava_dosyasi_id)===String(dosyaId)).map(x=>String(x.muvekkil_id)));return MUVEKKIL_KARTLARI.filter(m=>ids.has(String(m.id))).map(m=>m.ad).join(', ');}
function dosyaMaliSecimiDevam(){const id=document.getElementById('dosya-mali-secim-dosya').value,tur=document.getElementById('dosya-mali-secim-tur').value,msg=document.getElementById('dosya-mali-secim-msg');if(!id){msg.textContent='Önce bir dava dosyası seçin.';return;}document.getElementById('dosya-mali-secim-overlay').style.display='none';const d=DAVA_DOSYALARI.find(x=>String(x.id)===String(id));if(tur==='anlasilan')anlasilanUcretDuzenle(id,Number(d?.anlasilan_ucret)||0);else openMaliHareketFormu(id,tur);}
function openMaliHareketFormu(dosyaId,tur,hareketId=null){let o=document.getElementById('mali-hareket-overlay');if(!o){o=document.createElement('div');o.id='mali-hareket-overlay';o.className='modal-overlay';o.style.zIndex='550';document.body.appendChild(o);}const mevcut=hareketId?MALI_HAREKETLER.find(x=>String(x.id)===String(hareketId)):null,baslik={tahsilat:'Ücret Tahsilatı',masraf:'Masraf',masraf_tahsilati:'Masraf Tahsilatı'}[tur]||'Mali Hareket',kisiEtiketi=tur==='masraf'?'Ödeme yapılan kişi / kurum':'Ödemeyi yapan kişi',d=DAVA_DOSYALARI.find(x=>String(x.id)===String(dosyaId)),muvekkiller=dosyaMuvekkilAdlari(dosyaId)||'Müvekkil bağlanmamış',aciklamaParcalari=String(mevcut?.aciklama||'').split(' — '),kisi=aciklamaParcalari.length>1?aciklamaParcalari.shift():'',not=aciklamaParcalari.length?aciklamaParcalari.join(' — '):String(mevcut?.aciklama||'');o.innerHTML=`<div class="modal" style="max-width:460px;"><div class="modal-header"><h2>${baslik} ${mevcut?'Düzenle':'Ekle'}</h2><button class="btn" onclick="document.getElementById('mali-hareket-overlay').style.display='none'">✕</button></div><div class="modal-body"><div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px 12px;margin-bottom:13px;"><div style="font-size:10px;color:var(--text3);">Dava Dosyası</div><b style="font-size:13px;display:block;margin-top:2px;">${esc(d?.dosya_no||'Numarasız dosya')}</b><div style="font-size:10px;color:var(--text3);margin-top:7px;">Müvekkil</div><div style="font-size:12px;margin-top:2px;">${esc(muvekkiller)}</div></div><div class="fg"><label>Tutar (₺)</label><input id="mali-tutar" type="number" min="0.01" step="0.01" value="${mevcut?Number(mevcut.tutar):''}"></div><div class="fg"><label>Tarih</label><input id="mali-tarih" type="date" value="${mevcut?.tarih||new Date().toISOString().slice(0,10)}"></div><div class="fg"><label>${kisiEtiketi}</label><input id="mali-kisi" value="${esc(kisi)}" placeholder="Ad soyad veya kurum adı"></div><div class="fg"><label>Açıklama</label><input id="mali-aciklama" value="${esc(not)}" placeholder="Örn. İlk taksit, bilirkişi ücreti"></div><button class="save-btn" onclick="maliHareketKaydet('${dosyaId}','${tur}',${hareketId?`'${hareketId}'`:'null'})">${mevcut?'Değişiklikleri Kaydet':'Kaydet'}</button>${mevcut?`<button class="btn" style="width:100%;margin-top:8px;color:#dc2626;" onclick="maliHareketSil('${hareketId}','${dosyaId}')">Bu Kaydı Sil</button>`:''}<div id="mali-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';}
function maliHareketDuzenle(id,dosyaId){const x=MALI_HAREKETLER.find(h=>String(h.id)===String(id));if(!x){alert('Kayıt bulunamadı. Mali tabloyu yenileyip tekrar deneyin.');return;}openMaliHareketFormu(dosyaId,x.tur,id);}
function maliHareketDuzenlemeButonlariniEkle(){document.querySelectorAll('button[onclick^="maliHareketSil("]').forEach(sil=>{if(sil.parentElement?.querySelector('.mali-hareket-duzenle, button[onclick^="maliHareketDuzenle("]'))return;const kod=sil.getAttribute('onclick')||'',m=kod.match(/maliHareketSil\(['"]?([^,'"]+)['"]?\s*,\s*['"]?([^)'"]+)['"]?\)/);if(!m)return;const b=document.createElement('button');b.type='button';b.className='icon-btn mali-hareket-duzenle';b.textContent='Düzenle';b.onclick=()=>maliHareketDuzenle(m[1],m[2]);sil.parentElement.insertBefore(b,sil);});}
async function maliHareketKaydet(dosyaId,tur,hareketId=null){const tutar=Number(document.getElementById('mali-tutar').value),tarih=document.getElementById('mali-tarih').value,kisi=document.getElementById('mali-kisi')?.value.trim()||'',not=document.getElementById('mali-aciklama').value.trim(),aciklama=[kisi,not].filter(Boolean).join(' — '),msg=document.getElementById('mali-msg');if(!(tutar>0)||!tarih){msg.textContent='Geçerli tutar ve tarih girin.';return;}const veri={dava_dosyasi_id:dosyaId,tur,tutar,tarih,aciklama:aciklama||null};if(hareketId){const{data,error}=await sb.from('dosya_mali_hareketleri').update(veri).eq('id',hareketId).select('id,tarih,tutar').maybeSingle();if(error){msg.textContent='Güncelleme hatası: '+error.message;return;}if(!data){msg.textContent='Kayıt güncellenemedi. Supabase güncelleme izninin kurulması gerekiyor.';return;}}else{const{error}=await sb.from('dosya_mali_hareketleri').insert({...veri,buro_id:_buro.id,created_by:_user.id});if(error){msg.textContent='Hata: '+error.message;return;}}document.getElementById('mali-hareket-overlay').style.display='none';await maliTakipYukle();maliAltSekmeAc('dosya');}
function anlasilanUcretDuzenle(dosyaId,mevcut){
  let o=document.getElementById('anlasilan-ucret-overlay');if(!o){o=document.createElement('div');o.id='anlasilan-ucret-overlay';o.className='modal-overlay';o.style.zIndex='555';document.body.appendChild(o);}
  o.onclick=e=>{if(e.target===o)o.style.display='none';};
  const d=DAVA_DOSYALARI.find(x=>String(x.id)===String(dosyaId)),not=d?.ucret_anlasma_notu||'';
  const nispi=d?.ucret_turu==='nispi';
  o.innerHTML=`<div class="modal" style="max-width:500px;"><div class="modal-header"><div><h2>Ücret Anlaşması</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">${esc(d?.dosya_no||'Dosya')} · ${esc(dosyaMuvekkilAdlari(dosyaId)||'Müvekkil bağlanmamış')}</div></div><button class="btn" onclick="document.getElementById('anlasilan-ucret-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Ücret türü</label><select id="anlasilan-ucret-turu" onchange="ucretAnlasmaTuruDegisti()"><option value="maktu" ${!nispi?'selected':''}>Maktu (sabit tutar)</option><option value="nispi" ${nispi?'selected':''}>Nispi (oran üzerinden)</option></select></div><div id="maktu-ucret-alani" class="fg"><label>Toplam anlaşılan ücret (₺)</label><input id="anlasilan-ucret-tutar" type="number" min="0" step="0.01" value="${Number(mevcut)||''}" placeholder="Örn. 50000"></div><div id="nispi-ucret-alani" style="display:none;grid-template-columns:1fr 1fr;gap:9px;"><div class="fg"><label>Nispi oran (%)</label><input id="anlasilan-nispi-oran" type="number" min="0" max="100" step="0.01" value="${Number(d?.nispi_oran)||''}" oninput="nispiUcretOnizleme()"></div><div class="fg"><label>Tahmini hesap değeri (₺)</label><input id="anlasilan-nispi-deger" type="number" min="0" step="0.01" value="${Number(d?.nispi_hesap_degeri)||''}" oninput="nispiUcretOnizleme()"></div></div><div id="nispi-ucret-onizleme" style="display:none;padding:9px;background:#eff6ff;border-radius:8px;font-size:11px;margin-bottom:11px;"></div><div class="fg"><label>Beklenen tahsilat tarihi (opsiyonel)</label><input id="anlasilan-beklenen-tarih" type="date" value="${esc(d?.beklenen_tahsilat_tarihi||'')}"><div style="font-size:10px;color:var(--text3);margin-top:4px;">Genel bakışta gelecek ayların tahmini tahsilatı olarak gösterilir.</div></div><div class="fg"><label>Anlaşma koşulları</label><textarea id="anlasilan-ucret-notu" rows="6" placeholder="Örn. Tahsil edilen miktarın %15'i; yargılama giderleri hariçtir.">${esc(not)}</textarea></div><button id="anlasilan-ucret-kaydet" class="save-btn" onclick="anlasilanUcretKaydet('${dosyaId}')">Anlaşmayı Kaydet</button>${(Number(mevcut)>0||not||nispi)?`<button class="btn" style="width:100%;margin-top:8px;color:#dc2626;" onclick="ucretAnlasmasiniSil('${dosyaId}')">Ücret Anlaşmasını Sil</button>`:''}<div id="anlasilan-ucret-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;
  ucretAnlasmaTuruDegisti();
  o.style.display='flex';setTimeout(()=>document.getElementById('anlasilan-ucret-tutar')?.focus(),50);
}
function ucretAnlasmaTuruDegisti(){const nispi=document.getElementById('anlasilan-ucret-turu')?.value==='nispi',m=document.getElementById('maktu-ucret-alani'),n=document.getElementById('nispi-ucret-alani');if(m)m.style.display=nispi?'none':'block';if(n)n.style.display=nispi?'grid':'none';nispiUcretOnizleme();}
function nispiUcretOnizleme(){const o=document.getElementById('nispi-ucret-onizleme');if(!o)return;const nispi=document.getElementById('anlasilan-ucret-turu')?.value==='nispi',oran=Number(document.getElementById('anlasilan-nispi-oran')?.value)||0,deger=Number(document.getElementById('anlasilan-nispi-deger')?.value)||0;o.style.display=nispi?'block':'none';if(nispi)o.innerHTML=`Bugünkü tahmini değere göre ücret: <b>${tl(deger*oran/100)}</b><br><span style="color:var(--text3);">Bu tutar tahminidir; hesap değeri değiştikçe güncellenebilir.</span>`;}
async function anlasilanUcretKaydet(dosyaId){
  const tur=document.getElementById('anlasilan-ucret-turu').value,tutar=Number(document.getElementById('anlasilan-ucret-tutar').value)||0,oran=Number(document.getElementById('anlasilan-nispi-oran').value)||0,deger=Number(document.getElementById('anlasilan-nispi-deger').value)||0,beklenen=document.getElementById('anlasilan-beklenen-tarih').value||null,not=document.getElementById('anlasilan-ucret-notu').value.trim(),msg=document.getElementById('anlasilan-ucret-msg'),btn=document.getElementById('anlasilan-ucret-kaydet');
  if(tur==='maktu'&&(tutar<0||!Number.isFinite(tutar))){msg.textContent='Geçerli bir tutar girin.';return;}if(tur==='nispi'&&(!(oran>0)||oran>100||!(deger>0))){msg.textContent='Nispi ücret için geçerli oran ve tahmini hesap değeri girin.';return;}
  const veri={ucret_turu:tur,anlasilan_ucret:tur==='maktu'?tutar:0,nispi_oran:tur==='nispi'?oran:null,nispi_hesap_degeri:tur==='nispi'?deger:null,beklenen_tahsilat_tarihi:beklenen,ucret_anlasma_notu:not||null,updated_at:new Date().toISOString()};btn.disabled=true;btn.textContent='Kaydediliyor...';const{data:kayit,error}=await sb.from('dava_dosyalari').update(veri).eq('id',dosyaId).select('*').single();
  if(error){msg.textContent='Hata: '+error.message;msg.style.color='#dc2626';btn.disabled=false;btn.textContent='Ücreti Kaydet';return;}
  const d=DAVA_DOSYALARI.find(x=>String(x.id)===String(dosyaId));if(d)Object.assign(d,kayit||veri);document.getElementById('anlasilan-ucret-overlay').style.display='none';await maliTakipYukle();
}
async function ucretAnlasmasiniSil(dosyaId){if(!confirm('Bu dosyanın ücret anlaşmasıyla birlikte bütün tahsilat ve masraf kayıtları da silinecek. Devam edilsin mi?'))return;const msg=document.getElementById('anlasilan-ucret-msg'),h=await sb.from('dosya_mali_hareketleri').delete().eq('dava_dosyasi_id',dosyaId);if(h.error){if(msg)msg.textContent='Para hareketleri silinemedi: '+h.error.message;else alert('Para hareketleri silinemedi: '+h.error.message);return;}const temiz={ucret_turu:'maktu',anlasilan_ucret:0,nispi_oran:null,nispi_hesap_degeri:null,beklenen_tahsilat_tarihi:null,ucret_anlasma_notu:null,updated_at:new Date().toISOString()},{error}=await sb.from('dava_dosyalari').update(temiz).eq('id',dosyaId);if(error){if(msg)msg.textContent='Anlaşma silinemedi: '+error.message;else alert('Anlaşma silinemedi: '+error.message);return;}const d=DAVA_DOSYALARI.find(x=>String(x.id)===String(dosyaId));if(d)Object.assign(d,temiz);const o=document.getElementById('anlasilan-ucret-overlay');if(o)o.style.display='none';await maliTakipYukle();alert('Ücret anlaşması ve bağlı para hareketleri silindi.');}
async function maliHareketSil(id,dosyaId){if(!confirm('Bu mali hareket silinsin mi?'))return;const{error}=await sb.from('dosya_mali_hareketleri').delete().eq('id',id);if(error){alert('Hata: '+error.message);return;}if(document.getElementById('view-mali')?.classList.contains('active'))await maliTakipYukle();else await openBuroKartDetay('dosya',dosyaId);}
async function dosyaEkBilgilerHTML(dosyaId){
  const[i,e]=await Promise.all([sb.from('dosya_islem_gecmisi').select('*').eq('dava_dosyasi_id',dosyaId).order('islem_tarihi',{ascending:false}),sb.from('dosya_evraklari').select('*').eq('dava_dosyasi_id',dosyaId).order('created_at',{ascending:false})]);
  if(i.error||e.error)return `<div style="padding:11px;background:#fff7ed;border-radius:9px;font-size:11px;margin-bottom:14px;">Evrak ve işlem geçmişi kurulumu bekleniyor.</div>`;
  const islem=i.data||[],evrak=e.data||[],kat={dilekce:'Dilekçe',karar:'Karar',rapor:'Rapor',dekont:'Dekont',tebligat:'Tebligat',diger:'Diğer'};
  return `<div class="section-title">Evraklar <span>(${evrak.length})</span></div><div class="list-surface" style="margin-bottom:10px;">${evrak.length?evrak.map(x=>`<div style="padding:9px 11px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:8px;align-items:center;"><div><b style="font-size:12px;">${esc(x.dosya_adi)}</b><div style="font-size:10px;color:var(--text2);">${kat[x.kategori]||'Diğer'} · ${new Date(x.created_at).toLocaleDateString('tr-TR')}${x.aciklama?' · '+esc(x.aciklama):''}</div></div><div style="white-space:nowrap;"><button class="icon-btn" onclick="evrakAc(${x.id})">Aç</button><button class="icon-btn del" onclick="evrakSil(${x.id},${dosyaId})">Sil</button></div></div>`).join(''):'<div class="empty-state" style="padding:13px;">Henüz evrak eklenmedi.</div>'}</div><button class="btn btn-primary" style="margin-bottom:16px;" onclick="openEvrakFormu(${dosyaId})">＋ Evrak Yükle</button><div class="section-title">İşlem Geçmişi</div><div class="list-surface" style="margin-bottom:10px;">${islem.length?islem.map(x=>`<div style="padding:9px 11px;border-bottom:1px solid var(--border);"><div style="font-size:12px;">${esc(x.aciklama)}</div><div style="font-size:10px;color:var(--text3);margin-top:3px;">${new Date(x.islem_tarihi).toLocaleString('tr-TR')} · <button style="border:0;background:none;color:#dc2626;cursor:pointer;padding:0;" onclick="dosyaIslemiSil(${x.id},${dosyaId})">Sil</button></div></div>`).join(''):'<div class="empty-state" style="padding:13px;">Henüz işlem notu yok.</div>'}</div><button class="btn" style="margin-bottom:16px;" onclick="openDosyaIslemFormu(${dosyaId})">＋ İşlem Notu Ekle</button>`;
}
function openDosyaIslemFormu(dosyaId){let o=document.getElementById('dosya-islem-overlay');if(!o){o=document.createElement('div');o.id='dosya-islem-overlay';o.className='modal-overlay';o.style.zIndex='550';document.body.appendChild(o);}o.innerHTML=`<div class="modal" style="max-width:450px;"><div class="modal-header"><h2>İşlem Notu Ekle</h2><button class="btn" onclick="document.getElementById('dosya-islem-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Yapılan işlem</label><textarea id="dosya-islem-aciklama" placeholder="Örn. Müvekkil arandı, dilekçe hazırlandı..."></textarea></div><button class="save-btn" onclick="dosyaIslemiKaydet(${dosyaId})">Kaydet</button><div id="dosya-islem-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';}
async function dosyaAkisiniYenile(dosyaId){if(AKTIF_KAYIT_DETAY_ID&&document.getElementById('kayit-modal')?.style.display==='flex')await openKayitModal(AKTIF_KAYIT_DETAY_ID);else await openBuroKartDetay('dosya',dosyaId);}
async function dosyaIslemiKaydet(dosyaId){const aciklama=document.getElementById('dosya-islem-aciklama').value.trim(),msg=document.getElementById('dosya-islem-msg');if(!aciklama){msg.textContent='İşlem açıklaması yazın.';return;}const{error}=await sb.from('dosya_islem_gecmisi').insert({buro_id:_buro.id,dava_dosyasi_id:dosyaId,aciklama,created_by:_user.id});if(error){msg.textContent='Hata: '+error.message;return;}document.getElementById('dosya-islem-overlay').style.display='none';await dosyaAkisiniYenile(dosyaId);}
async function dosyaIslemiSil(id,dosyaId){if(!confirm('İşlem notu silinsin mi?'))return;const{error}=await sb.from('dosya_islem_gecmisi').delete().eq('id',id);if(error){alert('Hata: '+error.message);return;}await dosyaAkisiniYenile(dosyaId);}
function openEvrakFormu(dosyaId){let o=document.getElementById('evrak-overlay');if(!o){o=document.createElement('div');o.id='evrak-overlay';o.className='modal-overlay';o.style.zIndex='555';document.body.appendChild(o);}o.innerHTML=`<div class="modal" style="max-width:470px;"><div class="modal-header"><h2>Dosyaya Evrak Yükle</h2><button class="btn" onclick="document.getElementById('evrak-overlay').style.display='none'">✕</button></div><div class="modal-body"><div class="fg"><label>Dosya</label><input id="evrak-file" type="file"></div><div class="fg"><label>Kategori</label><select id="evrak-kategori"><option value="dilekce">Dilekçe</option><option value="karar">Karar</option><option value="rapor">Rapor</option><option value="dekont">Dekont</option><option value="tebligat">Tebligat</option><option value="diger">Diğer</option></select></div><div class="fg"><label>Açıklama</label><input id="evrak-aciklama" placeholder="İsteğe bağlı"></div><button id="evrak-kaydet" class="save-btn" onclick="evrakYukle(${dosyaId})">Evrakı Yükle</button><div id="evrak-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;o.style.display='flex';}
async function evrakYukle(dosyaId){const file=document.getElementById('evrak-file').files[0],msg=document.getElementById('evrak-msg'),btn=document.getElementById('evrak-kaydet');if(!file){msg.textContent='Yüklenecek dosyayı seçin.';return;}if(file.size>25*1024*1024){msg.textContent='Dosya en fazla 25 MB olabilir.';return;}btn.disabled=true;btn.textContent='Yükleniyor...';const temiz=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),yol=_buro.id+'/'+dosyaId+'/'+Date.now()+'-'+temiz,{error:yukHata}=await sb.storage.from('sekreter-evraklari').upload(yol,file);if(yukHata){msg.textContent='Yükleme hatası: '+yukHata.message;btn.disabled=false;btn.textContent='Evrakı Yükle';return;}const{error}=await sb.from('dosya_evraklari').insert({buro_id:_buro.id,dava_dosyasi_id:dosyaId,dosya_adi:file.name,storage_yolu:yol,mime_type:file.type||null,boyut:file.size,kategori:document.getElementById('evrak-kategori').value,aciklama:document.getElementById('evrak-aciklama').value.trim()||null,created_by:_user.id});if(error){await sb.storage.from('sekreter-evraklari').remove([yol]);msg.textContent='Kayıt hatası: '+error.message;return;}document.getElementById('evrak-overlay').style.display='none';await dosyaAkisiniYenile(dosyaId);}
async function evrakAc(id){const{data:r,error}=await sb.from('dosya_evraklari').select('storage_yolu').eq('id',id).single();if(error){alert('Evrak bulunamadı.');return;}const{data,error:h}=await sb.storage.from('sekreter-evraklari').createSignedUrl(r.storage_yolu,60);if(h){alert('Evrak açılamadı: '+h.message);return;}window.open(data.signedUrl,'_blank');}
async function evrakSil(id,dosyaId){if(!confirm('Evrak kalıcı olarak silinsin mi?'))return;const{data:r,error}=await sb.from('dosya_evraklari').select('storage_yolu').eq('id',id).single();if(error){alert('Evrak bulunamadı.');return;}const{error:s}=await sb.storage.from('sekreter-evraklari').remove([r.storage_yolu]);if(s){alert('Dosya silinemedi: '+s.message);return;}const{error:k}=await sb.from('dosya_evraklari').delete().eq('id',id);if(k){alert('Kayıt silinemedi: '+k.message);return;}await dosyaAkisiniYenile(dosyaId);}
async function openBuroKartDetay(tur,id){
  let o=document.getElementById('buro-kart-detay-overlay');if(!o){o=document.createElement('div');o.id='buro-kart-detay-overlay';o.className='modal-overlay';o.style.zIndex='515';document.body.appendChild(o);}o.onclick=e=>{if(e.target===o)closeBuroKartDetay();};o.innerHTML='<div class="modal" style="max-width:720px;"><div class="modal-body" style="padding:30px;text-align:center;color:var(--text2);">Yükleniyor...</div></div>';o.style.display='flex';
  try{
    if(tur==='muvekkil'){
      const m=MUVEKKIL_KARTLARI.find(x=>String(x.id)===String(id));if(!m)throw new Error('Müvekkil bulunamadı.');
      const{data:baglar,error}=await sb.from('dava_dosyasi_muvekkilleri').select('dava_dosyasi_id').eq('muvekkil_id',id);if(error)throw error;
      const idler=new Set((baglar||[]).map(x=>String(x.dava_dosyasi_id))),dosyalar=DAVA_DOSYALARI.filter(d=>idler.has(String(d.id)));
      const isler=records.filter(r=>String(r.muvekkilId||'')===String(id)||muvekkilAdiAnahtari(r.muvekkil)===muvekkilAdiAnahtari(m.ad));
      const geciken=isler.filter(r=>!r.tamamlandi&&new Date(r.date+'T12:00:00')<new Date(new Date().setHours(0,0,0,0))).length;
      o.innerHTML=`<div class="modal" style="max-width:720px;"><div class="modal-header"><div><h2>${esc(m.ad)}</h2><div style="font-size:11px;color:var(--text2);margin-top:2px;">${dosyalar.length} dosya · ${isler.length} iş · ${geciken} geciken</div></div><button class="btn" onclick="closeBuroKartDetay()">✕</button></div><div class="modal-body"><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-bottom:16px;">${[['Telefon',m.telefon],['E-posta',m.email],['Kimlik / Vergi No',m.kimlik_vergi_no],['Adres',m.adres]].map(x=>`<div style="background:var(--surface2);border-radius:9px;padding:9px 11px;"><div style="font-size:10px;color:var(--text3);">${x[0]}</div><div style="font-size:12px;margin-top:2px;white-space:pre-wrap;">${esc(x[1]||'—')}</div></div>`).join('')}</div>${m.notlar?`<div style="font-size:12px;padding:10px;background:#fffaf0;border-radius:9px;margin-bottom:15px;white-space:pre-wrap;">${esc(m.notlar)}</div>`:''}<div class="section-title">Bağlı Dosyalar</div><div class="list-surface" style="margin-bottom:16px;">${dosyalar.length?dosyalar.map(d=>`<div style="padding:9px 11px;border-bottom:1px solid var(--border);cursor:pointer;" onclick="openBuroKartDetay('dosya',${d.id})"><b style="font-size:12px;">${esc(d.dosya_no||'Dosya')}</b><div style="font-size:10px;color:var(--text2);margin-top:2px;">${esc([d.mahkeme,d.konu].filter(Boolean).join(' · '))}</div></div>`).join(''):'<div class="empty-state" style="padding:14px;">Bağlı dosya yok.</div>'}</div><div class="section-title">Takvim Kayıtları</div><div class="list-surface">${kartDetayKayitlariHTML(isler)}</div><button class="btn btn-primary" style="width:100%;margin-top:14px;" onclick="closeBuroKartDetay();openMuvekkilKartFormu(${m.id})">Müvekkil Bilgilerini Düzenle</button></div></div>`;
    }else{
      const d=DAVA_DOSYALARI.find(x=>String(x.id)===String(id));if(!d)throw new Error('Dosya bulunamadı.');
      const{data:baglar,error}=await sb.from('dava_dosyasi_muvekkilleri').select('muvekkil_id').eq('dava_dosyasi_id',id);if(error)throw error;
      const idler=new Set((baglar||[]).map(x=>String(x.muvekkil_id))),muvekkiller=MUVEKKIL_KARTLARI.filter(m=>idler.has(String(m.id)));
      const isler=records.filter(r=>String(r.davaDosyasiId||'')===String(id)||dosyaAnahtari(r.dava,r.mahkeme)===dosyaAnahtari(d.dosya_no,d.mahkeme)),ekBilgilerHTML=await dosyaEkBilgilerHTML(id);
      o.innerHTML=`<div class="modal" style="max-width:720px;"><div class="modal-header"><div><h2>${esc(d.dosya_no||'Dava Dosyası')}</h2><div style="font-size:11px;color:var(--text2);margin-top:2px;">${esc(d.durum||'açık')} · ${muvekkiller.length} müvekkil · ${isler.length} iş</div></div><button class="btn" onclick="closeBuroKartDetay()">✕</button></div><div class="modal-body"><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-bottom:16px;">${[['Mahkeme',d.mahkeme],['Konu',d.konu],['Durum',d.durum]].map(x=>`<div style="background:var(--surface2);border-radius:9px;padding:9px 11px;"><div style="font-size:10px;color:var(--text3);">${x[0]}</div><div style="font-size:12px;margin-top:2px;">${esc(x[1]||'—')}</div></div>`).join('')}</div>${d.notlar?`<div style="font-size:12px;padding:10px;background:#fffaf0;border-radius:9px;margin-bottom:15px;white-space:pre-wrap;">${esc(d.notlar)}</div>`:''}<div class="section-title">Bağlı Müvekkiller</div><div class="list-surface" style="margin-bottom:16px;">${muvekkiller.length?muvekkiller.map(m=>`<div style="padding:9px 11px;border-bottom:1px solid var(--border);cursor:pointer;" onclick="openBuroKartDetay('muvekkil',${m.id})"><b style="font-size:12px;">${esc(m.ad)}</b><div style="font-size:10px;color:var(--text2);margin-top:2px;">${esc([m.telefon,m.email].filter(Boolean).join(' · '))}</div></div>`).join(''):'<div class="empty-state" style="padding:14px;">Bağlı müvekkil yok.</div>'}</div><div class="section-title">Dosyanın Takvim Kayıtları</div><div class="list-surface">${kartDetayKayitlariHTML(isler)}</div><button class="btn btn-primary" style="width:100%;margin-top:14px;" onclick="closeBuroKartDetay();openDosyaKartFormu(${d.id})">Dosya Bilgilerini Düzenle</button></div></div>`;
      const takvimBaslik=[...o.querySelectorAll('.section-title')].find(x=>x.textContent==='Dosyanın Takvim Kayıtları');if(takvimBaslik)takvimBaslik.insertAdjacentHTML('beforebegin',ekBilgilerHTML);
    }
    kartYonetimButonlariniEkle(tur,id);
  }catch(e){o.innerHTML=`<div class="modal" style="max-width:500px;"><div class="modal-body" style="padding:24px;color:#dc2626;">Detay yüklenemedi: ${esc(e.message||e)}<br><button class="btn" style="margin-top:12px;" onclick="closeBuroKartDetay()">Kapat</button></div></div>`;}
}
function buroKartFormu(tur,id){
  const kaynak=tur==='muvekkil'?MUVEKKIL_KARTLARI:DAVA_DOSYALARI,k=kaynak.find(x=>String(x.id)===String(id))||{};
  let o=document.getElementById('buro-kart-form-overlay');if(!o){o=document.createElement('div');o.id='buro-kart-form-overlay';o.className='modal-overlay';o.style.zIndex='520';document.body.appendChild(o);}
  o.onclick=e=>{if(e.target===o)o.style.display='none';};
  const alan=(label,key,type='text')=>`<div class="fg"><label>${label}</label>${type==='textarea'?`<textarea id="bk-${key}"></textarea>`:`<input id="bk-${key}" type="${type}">`}</div>`;
  const hukukAlanlari=['','Hukuk','Ceza','Aile','İş','Ticaret','Tüketici','İcra','İdare','Vergi','Tahkim','Arabuluculuk'];
  const tarafSifatlari=['','Davacı','Davalı','Alacaklı','Borçlu','Başvurucu','Karşı Taraf','Şikayetçi','Müşteki','Sanık','Katılan'];
  const bagliMuvekkiller=id?new Set(DOSYA_MUVEKKIL_BAGLARI.filter(x=>String(x.dava_dosyasi_id)===String(id)).map(x=>String(x.muvekkil_id))):new Set();
  const dosyaAlanlari=`<div class="fg"><label>Müvekkil(ler)</label><div id="bk-muvekkiller" style="border:1px solid var(--border2);border-radius:10px;max-height:150px;overflow:auto;background:var(--surface);">${MUVEKKIL_KARTLARI.length?MUVEKKIL_KARTLARI.map(m=>`<label style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-bottom:1px solid var(--border);cursor:pointer;font-size:12px;"><input type="checkbox" value="${m.id}" ${bagliMuvekkiller.has(String(m.id))?'checked':''} style="accent-color:var(--navy);">${esc(m.ad)}</label>`).join(''):'<div style="padding:12px;color:var(--text3);font-size:12px;">Kayıtlı müvekkil yok. Dosya müvekkilsiz kaydedilebilir.</div>'}</div><div style="font-size:10px;color:var(--text3);margin-top:4px;">Bir dosyaya birden fazla müvekkil bağlanabilir.</div></div>${alan('Mahkeme / Kurum','mahkeme')}<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">${alan('Dosya No','dosya_no')}${alan('Konu','konu')}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;"><div class="fg"><label>Hukuk Alanı</label><select id="bk-hukuk_alani">${hukukAlanlari.map(x=>`<option value="${x}">${x||'— Belirtilmedi —'}</option>`).join('')}</select></div><div class="fg"><label>Taraf Sıfatı</label><select id="bk-taraf_sifati">${tarafSifatlari.map(x=>`<option value="${x}">${x||'Taraf sıfatı seçin'}</option>`).join('')}</select></div></div>${alan('Karşı Taraf','karsi_taraf')}<div class="fg"><label>Durum</label><select id="bk-durum"><option value="acik">Açık</option><option value="kapali">Kapalı</option><option value="arsiv">Arşiv</option></select></div>${alan('Notlar','notlar','textarea')}`;
  o.innerHTML=`<div class="modal" style="max-width:650px;"><div class="modal-header"><h2>${id?'Kartı Düzenle':tur==='muvekkil'?'Yeni Müvekkil':'Yeni Dava Dosyası'}</h2><button class="btn" onclick="document.getElementById('buro-kart-form-overlay').style.display='none'">✕</button></div><div class="modal-body">${tur==='muvekkil'?[alan('Ad Soyad / Unvan','ad'),alan('Telefon','telefon','tel'),alan('E-posta','email','email'),alan('Adres','adres','textarea'),alan('Kimlik / Vergi No','kimlik_vergi_no'),alan('Notlar','notlar','textarea')].join(''):dosyaAlanlari}<button class="save-btn" onclick="buroKartiKaydet('${tur}',${id||'null'})">Kaydet</button><div id="bk-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;
  Object.keys(k).forEach(key=>{const el=document.getElementById('bk-'+key);if(el)el.value=k[key]||'';});
  if(tur==='dosya'){
    const liste=document.getElementById('bk-muvekkiller');
    if(liste){
      const baslik=liste.closest('.fg')?.querySelector(':scope > label');if(baslik)baslik.textContent='Müvekkil seçimi';
      liste.insertAdjacentHTML('beforebegin','<div class="bk-client-toolbar"><input id="bk-muvekkil-ara" type="search" placeholder="Kayıtlı müvekkillerde ara..." oninput="buroFormuMuvekkilFiltrele(this.value)"><button type="button" class="bk-client-add" onclick="openDosyaIcindenYeniMuvekkil()">＋ Yeni Müvekkil</button><span class="bk-client-count" id="bk-muvekkil-ozet">0 seçili</span></div>');
      liste.querySelectorAll('input[type="checkbox"]').forEach(cb=>cb.addEventListener('change',buroFormuMuvekkilOzetiniGuncelle));
      buroFormuMuvekkilOzetiniGuncelle();
    }
    const mahkemeInput=document.getElementById('bk-mahkeme');
    if(mahkemeInput){
      const wrap=document.createElement('div');wrap.className='mahkeme-wrap';mahkemeInput.parentNode.insertBefore(wrap,mahkemeInput);wrap.appendChild(mahkemeInput);
      const dd=document.createElement('div');dd.className='mahkeme-dropdown';dd.id='dd-bk-mahkeme';wrap.appendChild(dd);
      mahkemeInput.placeholder='Yazmaya başlayın; mahkeme ve kurumlar önerilsin';mahkemeInput.autocomplete='new-password';
      mahkemeInput.addEventListener('input',()=>showMahkemeDropdown('bk-mahkeme','dd-bk-mahkeme'));
      mahkemeInput.addEventListener('focus',()=>showMahkemeDropdown('bk-mahkeme','dd-bk-mahkeme'));
      mahkemeInput.addEventListener('blur',()=>setTimeout(()=>{dd.style.display='none';},200));
    }
  }
  o.style.display='flex';
}
function buroFormuMuvekkilOzetiniGuncelle(){
  const secili=document.querySelectorAll('#bk-muvekkiller input[type="checkbox"]:checked').length,el=document.getElementById('bk-muvekkil-ozet');if(el)el.textContent=secili?secili+' seçili':'Seçim yok';
}
function buroFormuMuvekkilFiltrele(q){
  const aranan=String(q||'').toLocaleLowerCase('tr-TR').trim();document.querySelectorAll('#bk-muvekkiller label').forEach(label=>{label.style.display=!aranan||label.textContent.toLocaleLowerCase('tr-TR').includes(aranan)?'flex':'none';});
}
function openDosyaIcindenYeniMuvekkil(){
  let o=document.getElementById('dosya-yeni-muvekkil-overlay');if(!o){o=document.createElement('div');o.id='dosya-yeni-muvekkil-overlay';o.className='modal-overlay';o.style.zIndex='540';document.body.appendChild(o);}
  o.onclick=e=>{if(e.target===o)closeDosyaYeniMuvekkil();};
  o.innerHTML=`<div class="modal" style="max-width:480px;"><div class="modal-header"><div><h2>Yeni Müvekkil</h2><div style="font-size:11px;color:var(--text2);margin-top:3px;">Dosya bilgilerin korunacak ve bu kişi otomatik seçilecek.</div></div><button class="btn" onclick="closeDosyaYeniMuvekkil()">✕</button></div><div class="modal-body"><div class="fg"><label>Ad Soyad / Unvan *</label><input id="dy-muvekkil-ad" type="text" autofocus></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;"><div class="fg"><label>Telefon</label><input id="dy-muvekkil-telefon" type="tel"></div><div class="fg"><label>E-posta</label><input id="dy-muvekkil-email" type="email"></div></div><button id="dy-muvekkil-kaydet" class="save-btn" onclick="dosyaIcindenYeniMuvekkilKaydet()">Müvekkili Ekle ve Seç</button><div id="dy-muvekkil-msg" style="font-size:12px;margin-top:8px;"></div></div></div>`;
  o.style.display='flex';setTimeout(()=>document.getElementById('dy-muvekkil-ad')?.focus(),50);
}
function closeDosyaYeniMuvekkil(){const o=document.getElementById('dosya-yeni-muvekkil-overlay');if(o)o.style.display='none';}
async function dosyaIcindenYeniMuvekkilKaydet(){
  const ad=(document.getElementById('dy-muvekkil-ad')?.value||'').trim(),telefon=(document.getElementById('dy-muvekkil-telefon')?.value||'').trim(),email=(document.getElementById('dy-muvekkil-email')?.value||'').trim(),msg=document.getElementById('dy-muvekkil-msg'),btn=document.getElementById('dy-muvekkil-kaydet');
  if(!ad){msg.textContent='Ad soyad veya unvan zorunludur.';return;}
  const mevcut=MUVEKKIL_KARTLARI.find(m=>muvekkilAdiAnahtari(m.ad)===muvekkilAdiAnahtari(ad));
  if(mevcut){dosyaFormunaMuvekkilEkle(mevcut);closeDosyaYeniMuvekkil();return;}
  btn.disabled=true;btn.textContent='Ekleniyor...';
  const{data,error}=await sb.from('muvekkiller').insert({buro_id:_buro.id,ad,telefon:telefon||null,email:email||null,created_by:_user.id}).select('*').single();
  if(error){msg.textContent='Müvekkil eklenemedi: '+error.message;msg.style.color='#dc2626';btn.disabled=false;btn.textContent='Müvekkili Ekle ve Seç';return;}
  MUVEKKIL_KARTLARI.push(data);dosyaFormunaMuvekkilEkle(data);closeDosyaYeniMuvekkil();
}
function dosyaFormunaMuvekkilEkle(m){
  const liste=document.getElementById('bk-muvekkiller');if(!liste)return;
  const bos=[...liste.children].find(x=>x.tagName==='DIV');if(bos)bos.remove();
  let cb=[...liste.querySelectorAll('input[type="checkbox"]')].find(x=>String(x.value)===String(m.id));
  if(!cb){const label=document.createElement('label');label.innerHTML=`<input type="checkbox" value="${m.id}" checked>${esc(m.ad)}`;liste.appendChild(label);cb=label.querySelector('input');cb.addEventListener('change',buroFormuMuvekkilOzetiniGuncelle);}
  cb.checked=true;cb.closest('label').style.display='flex';const ara=document.getElementById('bk-muvekkil-ara');if(ara)ara.value='';buroFormuMuvekkilOzetiniGuncelle();
}
function openMuvekkilKartFormu(id){buroKartFormu('muvekkil',id);}
function openDosyaKartFormu(id){buroKartFormu('dosya',id);}
async function buroKartiKaydet(tur,id){
  const keys=tur==='muvekkil'?['ad','telefon','email','adres','kimlik_vergi_no','notlar']:['dosya_no','mahkeme','konu','hukuk_alani','taraf_sifati','karsi_taraf','durum','notlar'];
  const veri={buro_id:_buro.id};keys.forEach(k=>veri[k]=(document.getElementById('bk-'+k)?.value||'').trim()||null);
  if(tur==='muvekkil'&&!veri.ad){document.getElementById('bk-msg').textContent='Ad soyad veya unvan zorunludur.';return;}
  if(tur==='dosya'&&veri.mahkeme)await ogrenMahkeme(veri.mahkeme);
  const tablo=tur==='muvekkil'?'muvekkiller':'dava_dosyalari';
  let sonuc=id?await sb.from(tablo).update({...veri,updated_at:new Date().toISOString()}).eq('id',id).select('id').single():await sb.from(tablo).insert(veri).select('id').single();
  if(sonuc.error){document.getElementById('bk-msg').textContent='Hata: '+sonuc.error.message;return;}
  if(tur==='dosya'){
    const dosyaId=id||sonuc.data.id,secilen=[...document.querySelectorAll('#bk-muvekkiller input:checked')].map(x=>Number(x.value));
    const mevcut=DOSYA_MUVEKKIL_BAGLARI.filter(x=>String(x.dava_dosyasi_id)===String(dosyaId)).map(x=>Number(x.muvekkil_id));
    const eklenecek=secilen.filter(x=>!mevcut.includes(x)),cikarilacak=mevcut.filter(x=>!secilen.includes(x));
    if(eklenecek.length){const{error:bagHata}=await sb.from('dava_dosyasi_muvekkilleri').insert(eklenecek.map(muvekkil_id=>({dava_dosyasi_id:dosyaId,muvekkil_id})));if(bagHata){document.getElementById('bk-msg').textContent='Müvekkiller bağlanamadı: '+bagHata.message;return;}}
    if(cikarilacak.length){const{error:silHata}=await sb.from('dava_dosyasi_muvekkilleri').delete().eq('dava_dosyasi_id',dosyaId).in('muvekkil_id',cikarilacak);if(silHata){document.getElementById('bk-msg').textContent='Müvekkil bağlantısı kaldırılamadı: '+silHata.message;return;}}
  }
  document.getElementById('buro-kart-form-overlay').style.display='none';await buroKartlariYukle();
}

function muvekkilAdiAnahtari(ad){return String(ad||'').trim().replace(/\s+/g,' ').toLocaleLowerCase('tr-TR');}
function mevcutMuvekkilAktarimPlani(){
  const adHaritasi=new Map();
  records.filter(r=>r.muvekkil&&r.muvekkil.trim()).forEach(r=>{
    const ad=r.muvekkil.trim().replace(/\s+/g,' '),key=muvekkilAdiAnahtari(ad);
    if(!adHaritasi.has(key))adHaritasi.set(key,{ad,kayitlar:[]});
    adHaritasi.get(key).kayitlar.push(r);
  });
  const mevcut=new Map(MUVEKKIL_KARTLARI.map(m=>[muvekkilAdiAnahtari(m.ad),m]));
  return [...adHaritasi.entries()].map(([key,x])=>({...x,key,mevcut:mevcut.get(key)||null})).sort((a,b)=>a.ad.localeCompare(b.ad,'tr'));
}
async function mevcutMuvekkilleriOnizle(){
  await buroKartlariYukle();
  const plan=mevcutMuvekkilAktarimPlani();
  if(!plan.length){alert('Eski kayıtlarda aktarılacak müvekkil adı bulunamadı.');return;}
  const yeni=plan.filter(x=>!x.mevcut).length,toplamKayit=plan.reduce((n,x)=>n+x.kayitlar.length,0);
  let o=document.getElementById('muvekkil-aktar-overlay');if(!o){o=document.createElement('div');o.id='muvekkil-aktar-overlay';o.className='modal-overlay';o.style.zIndex='530';document.body.appendChild(o);}
  o.onclick=e=>{if(e.target===o)o.style.display='none';};
  o.innerHTML=`<div class="modal" style="max-width:580px;"><div class="modal-header"><h2>Mevcut Müvekkilleri Aktar</h2><button class="btn" onclick="document.getElementById('muvekkil-aktar-overlay').style.display='none'">✕</button></div><div class="modal-body"><div style="font-size:13px;line-height:1.55;margin-bottom:12px;"><b>${plan.length}</b> benzersiz müvekkil ve <b>${toplamKayit}</b> bağlı kayıt bulundu. <b>${yeni}</b> yeni kart oluşturulacak; mevcut kartlar tekrar oluşturulmayacak.</div><div style="max-height:300px;overflow:auto;border:1px solid var(--border);border-radius:10px;">${plan.map(x=>`<div style="padding:8px 11px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:10px;"><span>${esc(x.ad)}</span><span style="font-size:11px;color:var(--text2);white-space:nowrap;">${x.kayitlar.length} kayıt · ${x.mevcut?'mevcut kart':'yeni kart'}</span></div>`).join('')}</div><div style="display:flex;gap:8px;margin-top:14px;"><button class="btn" style="flex:1;" onclick="document.getElementById('muvekkil-aktar-overlay').style.display='none'">Vazgeç</button><button id="muvekkil-aktar-btn" class="btn btn-primary" style="flex:1;" onclick="mevcutMuvekkilleriAktar()">Aktarımı Başlat</button></div><div id="muvekkil-aktar-msg" style="font-size:12px;margin-top:9px;"></div></div></div>`;
  o.style.display='flex';
}
async function mevcutMuvekkilleriAktar(){
  const btn=document.getElementById('muvekkil-aktar-btn'),msg=document.getElementById('muvekkil-aktar-msg');btn.disabled=true;btn.textContent='Aktarılıyor...';
  try{
    let plan=mevcutMuvekkilAktarimPlani(),yeniler=plan.filter(x=>!x.mevcut).map(x=>({buro_id:_buro.id,ad:x.ad,created_by:_user.id}));
    if(yeniler.length){const{error}=await sb.from('muvekkiller').insert(yeniler);if(error)throw error;}
    const{data:kartlar,error:kartHata}=await sb.from('muvekkiller').select('id,ad').eq('buro_id',_buro.id);if(kartHata)throw kartHata;
    const kartMap=new Map((kartlar||[]).map(k=>[muvekkilAdiAnahtari(k.ad),k.id]));
    let baglanan=0;
    for(const x of plan){
      const kartId=kartMap.get(x.key);if(!kartId)continue;
      const ids=x.kayitlar.map(r=>r.id);
      for(let i=0;i<ids.length;i+=100){const parca=ids.slice(i,i+100),{error}=await sb.from('kayitlar').update({muvekkil_id:kartId}).in('id',parca);if(error)throw error;baglanan+=parca.length;}
    }
    msg.textContent='✓ '+baglanan+' kayıt müvekkil kartlarına bağlandı.';btn.textContent='Tamamlandı';await buroKartlariYukle();setTimeout(()=>{document.getElementById('muvekkil-aktar-overlay').style.display='none';},1200);
  }catch(e){msg.textContent='Aktarım durdu: '+(e.message||e);msg.style.color='#dc2626';btn.disabled=false;btn.textContent='Tekrar Dene';}
}

function dosyaAnahtari(no,mahkeme){return muvekkilAdiAnahtari(no)+'|'+muvekkilAdiAnahtari(mahkeme);}
function mevcutDosyaAktarimPlani(){
  const harita=new Map();
  records.filter(r=>r.dava&&r.dava.trim()).forEach(r=>{
    const no=r.dava.trim(),mahkeme=(r.mahkeme||'').trim(),key=dosyaAnahtari(no,mahkeme);
    if(!harita.has(key))harita.set(key,{key,no,mahkeme,kayitlar:[]});harita.get(key).kayitlar.push(r);
  });
  const mevcut=new Map(DAVA_DOSYALARI.map(d=>[dosyaAnahtari(d.dosya_no,d.mahkeme),d]));
  return [...harita.values()].map(x=>({...x,mevcut:mevcut.get(x.key)||null})).sort((a,b)=>a.no.localeCompare(b.no,'tr'));
}
async function mevcutDosyalariOnizle(){
  await buroKartlariYukle();const plan=mevcutDosyaAktarimPlani();
  if(!plan.length){alert('Eski kayıtlarda aktarılacak dava dosyası numarası bulunamadı.');return;}
  const yeni=plan.filter(x=>!x.mevcut).length,toplam=plan.reduce((n,x)=>n+x.kayitlar.length,0);
  let o=document.getElementById('dosya-aktar-overlay');if(!o){o=document.createElement('div');o.id='dosya-aktar-overlay';o.className='modal-overlay';o.style.zIndex='530';document.body.appendChild(o);}o.onclick=e=>{if(e.target===o)o.style.display='none';};
  o.innerHTML=`<div class="modal" style="max-width:600px;"><div class="modal-header"><h2>Mevcut Dava Dosyalarını Aktar</h2><button class="btn" onclick="document.getElementById('dosya-aktar-overlay').style.display='none'">✕</button></div><div class="modal-body"><div style="font-size:13px;line-height:1.55;margin-bottom:12px;"><b>${plan.length}</b> farklı dosya ve <b>${toplam}</b> bağlı kayıt bulundu. <b>${yeni}</b> yeni dosya kartı oluşturulacak.</div><div style="max-height:300px;overflow:auto;border:1px solid var(--border);border-radius:10px;">${plan.map(x=>`<div style="padding:8px 11px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:10px;"><span><b>${esc(x.no)}</b>${x.mahkeme?'<br><small>'+esc(x.mahkeme)+'</small>':''}</span><span style="font-size:11px;color:var(--text2);white-space:nowrap;">${x.kayitlar.length} kayıt · ${x.mevcut?'mevcut':'yeni'}</span></div>`).join('')}</div><div style="display:flex;gap:8px;margin-top:14px;"><button class="btn" style="flex:1;" onclick="document.getElementById('dosya-aktar-overlay').style.display='none'">Vazgeç</button><button id="dosya-aktar-btn" class="btn btn-primary" style="flex:1;" onclick="mevcutDosyalariAktar()">Aktarımı Başlat</button></div><div id="dosya-aktar-msg" style="font-size:12px;margin-top:9px;"></div></div></div>`;o.style.display='flex';
}
async function mevcutDosyalariAktar(){
  const btn=document.getElementById('dosya-aktar-btn'),msg=document.getElementById('dosya-aktar-msg');btn.disabled=true;btn.textContent='Aktarılıyor...';
  try{
    const plan=mevcutDosyaAktarimPlani(),yeniler=plan.filter(x=>!x.mevcut).map(x=>({buro_id:_buro.id,dosya_no:x.no,mahkeme:x.mahkeme||null,created_by:_user.id}));
    if(yeniler.length){const{error}=await sb.from('dava_dosyalari').insert(yeniler);if(error)throw error;}
    const{data:kartlar,error:kartHata}=await sb.from('dava_dosyalari').select('id,dosya_no,mahkeme').eq('buro_id',_buro.id);if(kartHata)throw kartHata;
    const kartMap=new Map((kartlar||[]).map(k=>[dosyaAnahtari(k.dosya_no,k.mahkeme),k.id]));let baglanan=0;const iliskiler=[];
    for(const x of plan){
      const kartId=kartMap.get(x.key);if(!kartId)continue;const ids=x.kayitlar.map(r=>r.id);
      for(let i=0;i<ids.length;i+=100){const parca=ids.slice(i,i+100),{error}=await sb.from('kayitlar').update({dava_dosyasi_id:kartId}).in('id',parca);if(error)throw error;baglanan+=parca.length;}
      x.kayitlar.filter(r=>r.muvekkilId).forEach(r=>iliskiler.push({dava_dosyasi_id:kartId,muvekkil_id:r.muvekkilId}));
    }
    if(iliskiler.length){const benzersiz=[...new Map(iliskiler.map(x=>[x.dava_dosyasi_id+'|'+x.muvekkil_id,x])).values()];const{error}=await sb.from('dava_dosyasi_muvekkilleri').upsert(benzersiz,{onConflict:'dava_dosyasi_id,muvekkil_id',ignoreDuplicates:true});if(error)throw error;}
    msg.textContent='✓ '+baglanan+' kayıt dava dosyalarına bağlandı.';btn.textContent='Tamamlandı';await loadRecords();await buroKartlariYukle();setTimeout(()=>{document.getElementById('dosya-aktar-overlay').style.display='none';},1200);
  }catch(e){msg.textContent='Aktarım durdu: '+(e.message||e);msg.style.color='#dc2626';btn.disabled=false;btn.textContent='Tekrar Dene';}
}
